<template>
    <!-- 自定义导航栏 -->
    <view class="custom-nav">
        <common-nav-bar>
            <template #weather>
                <view class="weatherBox">
                    <image class="weatherImg" src="/static/images/weather/太阳.png" mode="aspectFill"></image>
                </view>
            </template>
            <template #text>
                <view class="text">健康饮食，从今天开始!</view>
            </template>
        </common-nav-bar>
    </view>

    <!-- 页面内容 -->
    <view class="content">
        <!-- 今日饮食概览 -->
        <view class="diet-overview">
            <view class="overview-title">今日饮食</view>
            <view class="calories-card">
                <view class="calories-info">
                    <text class="calories-number">{{ todayCalories }}</text>
                    <text class="calories-unit">kcal</text>
                </view>
                <view class="calories-progress">
                    <view class="progress-bar">
                        <view class="progress-fill" :style="{ width: caloriesProgress + '%' }"></view>
                    </view>
                    <text class="progress-text">目标: {{ calorieGoal }} kcal</text>
                </view>
            </view>
        </view>

        <!-- 快速记录 -->
        <view class="quick-record">
            <view class="section-title">快速记录</view>
            <view class="record-buttons">
                <button class="record-btn breakfast" @click="recordMeal('breakfast')">
                    <text class="btn-icon">🌅</text>
                    <text class="btn-text">早餐</text>
                </button>
                <button class="record-btn lunch" @click="recordMeal('lunch')">
                    <text class="btn-icon">☀️</text>
                    <text class="btn-text">午餐</text>
                </button>
                <button class="record-btn dinner" @click="recordMeal('dinner')">
                    <text class="btn-icon">🌙</text>
                    <text class="btn-text">晚餐</text>
                </button>
                <button class="record-btn snack" @click="recordMeal('snack')">
                    <text class="btn-icon">🍎</text>
                    <text class="btn-text">加餐</text>
                </button>
            </view>
        </view>

        <!-- 今日记录 -->
        <view class="today-records">
            <view class="section-title">今日记录</view>
            <view class="meal-list">
                <view class="meal-item" v-for="(meal, index) in todayMeals" :key="index">
                    <view class="meal-info">
                        <text class="meal-name">{{ meal.name }}</text>
                        <text class="meal-calories">{{ meal.calories }} kcal</text>
                    </view>
                    <view class="meal-time">{{ meal.time }}</view>
                </view>
            </view>
        </view>
    </view>
</template>

<script setup>
import { ref, onMounted } from 'vue'

// 数据
const todayCalories = ref(1200)
const calorieGoal = ref(2000)
const caloriesProgress = ref(60)
const todayMeals = ref([
    { name: '燕麦粥', calories: 300, time: '08:30' },
    { name: '苹果', calories: 80, time: '10:00' },
    { name: '鸡胸肉沙拉', calories: 450, time: '12:30' },
    { name: '酸奶', calories: 120, time: '15:00' }
])

// 记录餐食
const recordMeal = (mealType) => {
    uni.showToast({
        title: `记录${mealType}`,
        icon: 'success'
    })
    // 这里可以跳转到食物选择页面
}

onMounted(() => {
    // 加载今日饮食数据
})
</script>

<style lang="scss" scoped>
.custom-nav {
    .weatherBox {
        width: 90rpx;
        height: 90rpx;

        .weatherImg {
            width: 100%;
            height: 100%;
        }
    }
}

.content {
    padding: 20rpx;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
}

.diet-overview {
    margin-bottom: 30rpx;

    .overview-title {
        color: white;
        font-size: 36rpx;
        font-weight: bold;
        margin-bottom: 20rpx;
    }

    .calories-card {
        background: white;
        border-radius: 20rpx;
        padding: 30rpx;
        box-shadow: 0 8rpx 32rpx rgba(0, 0, 0, 0.1);

        .calories-info {
            display: flex;
            align-items: baseline;
            margin-bottom: 20rpx;

            .calories-number {
                font-size: 60rpx;
                font-weight: bold;
                color: #4CAF50;
            }

            .calories-unit {
                font-size: 24rpx;
                color: #666;
                margin-left: 10rpx;
            }
        }

        .calories-progress {
            .progress-bar {
                height: 12rpx;
                background: #f0f0f0;
                border-radius: 6rpx;
                overflow: hidden;
                margin-bottom: 10rpx;

                .progress-fill {
                    height: 100%;
                    background: linear-gradient(90deg, #4CAF50, #8BC34A);
                    border-radius: 6rpx;
                    transition: width 0.3s ease;
                }
            }

            .progress-text {
                font-size: 24rpx;
                color: #666;
            }
        }
    }
}

.quick-record {
    margin-bottom: 30rpx;

    .section-title {
        color: white;
        font-size: 32rpx;
        font-weight: bold;
        margin-bottom: 20rpx;
    }

    .record-buttons {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 20rpx;

        .record-btn {
            background: white;
            border: none;
            border-radius: 16rpx;
            padding: 30rpx 20rpx;
            display: flex;
            flex-direction: column;
            align-items: center;
            box-shadow: 0 4rpx 16rpx rgba(0, 0, 0, 0.1);
            transition: transform 0.2s ease;

            &:active {
                transform: scale(0.95);
            }

            .btn-icon {
                font-size: 40rpx;
                margin-bottom: 10rpx;
            }

            .btn-text {
                font-size: 28rpx;
                color: #333;
                font-weight: 500;
            }
        }
    }
}

.today-records {
    .section-title {
        color: white;
        font-size: 32rpx;
        font-weight: bold;
        margin-bottom: 20rpx;
    }

    .meal-list {
        background: white;
        border-radius: 20rpx;
        overflow: hidden;
        box-shadow: 0 8rpx 32rpx rgba(0, 0, 0, 0.1);

        .meal-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 30rpx;
            border-bottom: 1rpx solid #f0f0f0;

            &:last-child {
                border-bottom: none;
            }

            .meal-info {
                display: flex;
                flex-direction: column;

                .meal-name {
                    font-size: 32rpx;
                    color: #333;
                    font-weight: 500;
                    margin-bottom: 8rpx;
                }

                .meal-calories {
                    font-size: 24rpx;
                    color: #4CAF50;
                }
            }

            .meal-time {
                font-size: 24rpx;
                color: #999;
            }
        }
    }
}
</style>
